package bookstore

import "sort"

// Cost returns the cheapest price (in cents) for the given basket of books,
// applying the shop's discount schedule and choosing the grouping that gives
// the biggest possible discount.
func Cost(books []int) int {
	// Price of a group of n distinct books, in cents.
	prices := []int{800, 1520, 2160, 2560, 3000}

	// counts[i] is how many copies of book i+1 are in the basket.
	counts := [5]int{}
	for _, book := range books {
		counts[book-1]++
	}

	total := 0
	for {
		// Keep the most plentiful titles first so a group always grabs one
		// of each distinct title that still has copies left.
		sort.Sort(sort.Reverse(sort.IntSlice(counts[:5])))
		if counts[0] == 0 {
			break
		}

		// size is the number of distinct titles with copies remaining.
		size := 0
		for _, c := range counts {
			if c > 0 {
				size++
			}
		}

		// A group of five plus a later group of three costs 3000+2160=5160,
		// while two groups of four cost 2560+2560=5120. When the least
		// plentiful title has strictly fewer copies than the third most
		// plentiful one, taking a group of four now (leaving the rare title
		// for a later group) avoids that 5+3 split.
		if size == 5 && counts[4] < counts[2] {
			size = 4
		}

		total += prices[size-1]
		for i := 0; i < size; i++ {
			counts[i]--
		}
	}

	return total
}

